('riy3-mesele#32','riy-3-mesele',2,4,'Aslan 3 gündə 27 səhifə oxudu. Hər gün bərabər oxudusa, gündə neçə səhifə oxuyub?','27 : 3 = 9 səhifə.',array['9 səhifə','8 səhifə','24 səhifə','81 səhifə'],1),
('riy3-mesele#33','riy-3-mesele',3,4,'Avtobusda 42 sərnişin var idi. 17-si düşdü, 9-u mindi. İndi neçə sərnişin var?','42 − 17 + 9 = 34 sərnişin.',array['34 sərnişin','25 sərnişin','50 sərnişin','16 sərnişin'],1),
('riy3-mesele#34','riy-3-mesele',2,4,'Bir qutu şirənin qiyməti 2 manatdır. 14 manata neçə qutu almaq olar?','14 : 2 = 7 qutu.',array['7 qutu','6 qutu','28 qutu','12 qutu'],1),
('riy3-mesele#35','riy-3-mesele',3,4,'Həyətdə toyuq və cücələr var. Toyuqlar 12, cücələr ondan 3 dəfə çoxdur. Neçə cücə var?','12 × 3 = 36 cücə.',array['36 cücə','15 cücə','4 cücə','24 cücə'],1),
('riy3-mesele#36','riy-3-mesele',2,4,'Usta gündə 6 stul düzəldir. 5 gündə neçə stul düzəldər?','6 × 5 = 30 stul.',array['30 stul','11 stul','25 stul','35 stul'],1),
('riy3-mesele#37','riy-3-mesele',2,4,'Məktəbə 350 yeni kitab gətirildi. 3-cü siniflərə 140-ı verildi. Neçə kitab qaldı?','350 − 140 = 210 kitab.',array['210 kitab','220 kitab','200 kitab','490 kitab'],1),
