('riy3-mesele#39','riy-3-mesele',3,4,'Turist birinci gün 16 km, ikinci gün ondan 5 km çox yol getdi. İki gündə cəmi neçə km getdi?','İkinci gün: 21 km. Cəmi: 16 + 21 = 37 km.',array['37 km','21 km','32 km','42 km'],1),
('riy3-mesele#40','riy-3-mesele',1,4,'Məsələni həll etməzdən əvvəl nə etmək lazımdır?','Əvvəlcə şərti diqqətlə oxuyub anlamaq lazımdır.',array['Şərti diqqətlə oxumaq','Dərhal cavab yazmaq','Rəqəmləri toplamaq','Cavabı təxmin etmək'],1)
